const softDeleteDesign = `-- name: SoftDeleteDesign :execrows
UPDATE master_designs SET deleted_at = now() WHERE id = $1 AND deleted_at IS NULL
`

func (q *Queries) SoftDeleteDesign(ctx context.Context, id int64) (int64, error) {
	result, err := q.db.Exec(ctx, softDeleteDesign, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

