const upsertVariationWeight = `-- name: UpsertVariationWeight :exec
INSERT INTO variation_metal_weights (variation_id, metal_id, net_weight_g, gross_weight_g)
VALUES ($1, $2, $3, $4)
ON CONFLICT (variation_id, metal_id) DO UPDATE
SET net_weight_g = EXCLUDED.net_weight_g, gross_weight_g = EXCLUDED.gross_weight_g
`

type UpsertVariationWeightParams struct {
	VariationID  int64               `json:"variation_id"`
	MetalID      int64               `json:"metal_id"`
	NetWeightG   decimal.Decimal     `json:"net_weight_g"`
	GrossWeightG decimal.NullDecimal `json:"gross_weight_g"`
}

func (q *Queries) UpsertVariationWeight(ctx context.Context, arg UpsertVariationWeightParams) error {
	_, err := q.db.Exec(ctx, upsertVariationWeight,
		arg.VariationID,
		arg.MetalID,
		arg.NetWeightG,
		arg.GrossWeightG,
	)
	return err
}
